(() => {
  const modalEl = document.getElementById('fileManagerModal');
  if (!modalEl || typeof bootstrap === 'undefined') {
    return;
  }

  const listEl = document.getElementById('fileManagerList');
  const uploadForm = document.getElementById('fileManagerUploadForm');
  const uploadBtn = document.getElementById('fileManagerUploadBtn');
  const uploadStatus = document.getElementById('fileManagerUploadStatus');
  const urlInput = document.getElementById('fileManagerUrlInput');
  const insertUrlBtn = document.getElementById('fileManagerInsertUrlBtn');
  const fileInput = document.getElementById('fileManagerFileInput');
  const descriptionInput = document.getElementById('fileManagerDescription');
  const titleEl = modalEl.querySelector('[data-filemanager-title]');
  const listLabelEl = modalEl.querySelector('[data-filemanager-list-label]');
  const uploadLabelEl = modalEl.querySelector('[data-filemanager-upload-label]');
  const acceptHelpEl = modalEl.querySelector('[data-filemanager-accept-help]');
  const urlLabelEl = modalEl.querySelector('[data-filemanager-url-label]');

  const modal = bootstrap.Modal.getOrCreateInstance(modalEl);

  const defaultConfigs = {
    image: {
      title: 'Inserir Imagem',
      listLabel: 'Suas Imagens (Mais Recentes Primeiro)',
      uploadLabel: 'Fazer Upload de Nova Imagem',
      accept: 'image/*',
      acceptHelp: 'Formatos: JPG, PNG, GIF, WebP (máx. 500 MB)',
      urlPlaceholder: 'https://exemplo.com/imagem.jpg',
      endpoint: '/api/images',
      filetag: 'imagem',
      emptyText: 'Nenhuma imagem disponível',
    },
    video: {
      title: 'Inserir Vídeo',
      listLabel: 'Seus Vídeos (Mais Recentes Primeiro)',
      uploadLabel: 'Fazer Upload de Novo Vídeo',
      accept: 'video/*',
      acceptHelp: 'Formatos: MP4, WebM, OGG, MOV (máx. 500 MB)',
      urlPlaceholder: 'https://exemplo.com/video.mp4',
      endpoint: '/api/videos',
      filetag: 'video',
      emptyText: 'Nenhum vídeo disponível',
    },
    audio: {
      title: 'Inserir Áudio',
      listLabel: 'Seus Áudios (Mais Recentes Primeiro)',
      uploadLabel: 'Fazer Upload de Novo Áudio',
      accept: 'audio/*',
      acceptHelp: 'Formatos: MP3, OGG, WAV, FLAC (máx. 500 MB)',
      urlPlaceholder: 'https://exemplo.com/audio.mp3',
      endpoint: '/api/audios',
      filetag: 'audio',
      emptyText: 'Nenhum áudio disponível',
    },
  };

  const state = {
    type: 'image',
    onSelect: null,
    filetag: '',
    urlPlaceholder: '',
    trigger: null,
  };

  const getConfig = () => {
    const base = defaultConfigs[state.type] || defaultConfigs.image;
    return {
      ...base,
      filetag: state.filetag || base.filetag,
      urlPlaceholder: state.urlPlaceholder || base.urlPlaceholder,
    };
  };

  const setTextContent = () => {
    const cfg = getConfig();
    if (titleEl) titleEl.textContent = cfg.title;
    if (listLabelEl) listLabelEl.textContent = cfg.listLabel;
    if (uploadLabelEl) uploadLabelEl.textContent = cfg.uploadLabel;
    if (acceptHelpEl) acceptHelpEl.textContent = cfg.acceptHelp;
    if (urlLabelEl) urlLabelEl.textContent = 'Inserir URL Direta';
    if (fileInput) fileInput.accept = cfg.accept;
    if (urlInput) urlInput.placeholder = cfg.urlPlaceholder;
  };

  const sanitizeText = (text) => (text || '').replace(/</g, '&lt;').replace(/>/g, '&gt;');

  const stopMediaPlayback = () => {
    const mediaEls = modalEl.querySelectorAll('video, audio');
    mediaEls.forEach((media) => {
      if (typeof media.pause === 'function') {
        try {
          media.pause();
          if (Number.isFinite(media.currentTime)) {
            media.currentTime = 0;
          }
        } catch (err) {
          console.warn('[filemanager-modal] unable to pause media', err);
        }
      }
    });
  };

  const buildPreview = (item) => {
    const wrapper = document.createElement('div');
    wrapper.className = 'flex-shrink-0 d-flex align-items-center justify-content-center';
    if (state.type === 'video') {
      wrapper.style.width = '160px';
      wrapper.style.height = '100px';
      const video = document.createElement('video');
      video.src = item.file_url || '';
      video.controls = true;
      video.preload = 'metadata';
      video.className = 'rounded border bg-black';
      video.style.width = '100%';
      video.style.height = '100%';
      video.playsInline = true;
      const showFirstFrame = () => {
        try {
          video.currentTime = 0;
          if (video.paused === false) {
            video.pause();
          }
        } catch (err) {
          console.warn('[filemanager-modal] unable to show first frame', err);
        }
      };
      video.addEventListener('loadedmetadata', showFirstFrame, { once: true });
      video.addEventListener('loadeddata', showFirstFrame, { once: true });
      if (item.thumbnail_url) {
        video.poster = item.thumbnail_url;
      }
      wrapper.addEventListener('click', (event) => event.stopPropagation());
      wrapper.appendChild(video);
      return wrapper;
    }

    if (state.type === 'audio') {
      wrapper.style.minWidth = '200px';
      const audio = document.createElement('audio');
      audio.src = item.file_url || '';
      audio.controls = true;
      audio.preload = 'metadata';
      audio.className = 'w-100';
      wrapper.addEventListener('click', (event) => event.stopPropagation());
      wrapper.appendChild(audio);
      return wrapper;
    }

    wrapper.classList.add('rounded', 'overflow-hidden', 'bg-body-secondary');
    wrapper.style.width = '60px';
    wrapper.style.height = '60px';
    if (item.thumbnail_url || item.file_url) {
      const img = document.createElement('img');
      img.src = item.thumbnail_url || item.file_url;
      img.alt = sanitizeText(item.display_name) || 'Imagem';
      img.style.width = '100%';
      img.style.height = '100%';
      img.style.objectFit = 'contain';
      wrapper.appendChild(img);
      return wrapper;
    }

    const badge = document.createElement('span');
    badge.className = 'small text-body-secondary';
    badge.textContent = 'Imagem';
    wrapper.appendChild(badge);
    return wrapper;
  };

  const renderList = (items) => {
    if (!listEl) {
      return;
    }

    listEl.innerHTML = '';
    const cfg = getConfig();
    if (!items || items.length === 0) {
      listEl.innerHTML = `<div class="text-center text-body-secondary py-4"><small>${cfg.emptyText}</small></div>`;
      return;
    }

    const frag = document.createDocumentFragment();
    items.forEach((item) => {
      const row = document.createElement('div');
      row.className = 'd-flex align-items-start gap-3 border-bottom py-2 filemanager-row';
      row.dataset.url = item.file_url || '';

      const preview = buildPreview(item);

      const meta = document.createElement('div');
      meta.className = 'flex-grow-1';

      const title = document.createElement('div');
      title.className = 'small fw-bold';
      title.textContent = item.display_name || 'Arquivo';
      meta.appendChild(title);

      const desc = document.createElement('div');
      desc.className = 'small text-body-secondary text-truncate';
      desc.textContent = item.description || 'Sem descrição';
      meta.appendChild(desc);

      if (item.created_at) {
        const created = document.createElement('div');
        created.className = 'small text-body-secondary';
        created.textContent = item.created_at;
        meta.appendChild(created);
      }

      const useBtn = document.createElement('button');
      useBtn.type = 'button';
      useBtn.className = 'btn btn-sm btn-outline-primary';
      useBtn.textContent = 'Usar';
      useBtn.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        selectFile(item.file_url || '', item);
      });

      row.addEventListener('click', () => selectFile(item.file_url || '', item));

      row.appendChild(preview);
      row.appendChild(meta);
      row.appendChild(useBtn);

      frag.appendChild(row);
    });

    listEl.appendChild(frag);
  };

  const showLoading = () => {
    if (listEl) {
      listEl.innerHTML = '<div class="text-center text-body-secondary py-4"><small>Carregando...</small></div>';
    }
  };

  const loadList = async () => {
    const cfg = getConfig();
    showLoading();
    let response;
    try {
      response = await fetch(cfg.endpoint, { headers: { Accept: 'application/json' } });
    } catch (error) {
      console.error('[filemanager-modal] fetch error', error);
      if (listEl) {
        listEl.innerHTML = '<div class="alert alert-danger mb-0">Erro ao carregar arquivos</div>';
      }
      return;
    }

    if (!response.ok) {
      console.error('[filemanager-modal] response not ok', response.status);
      if (listEl) {
        listEl.innerHTML = '<div class="alert alert-danger mb-0">Erro ao carregar arquivos</div>';
      }
      return;
    }

    let items = [];
    try {
      items = await response.json();
    } catch (error) {
      console.error('[filemanager-modal] invalid JSON', error);
    }
    renderList(items);
  };

  const getCSRFToken = () => {
    const metaTag = document.querySelector('meta[name="csrf_token"]');
    return metaTag ? metaTag.getAttribute('content') : '';
  };

  const selectFile = (url, meta) => {
    const trimmed = (url || '').trim();
    if (!trimmed) {
      return;
    }

    stopMediaPlayback();

    if (typeof state.onSelect === 'function') {
      state.onSelect(trimmed, meta || {});
    }

    document.dispatchEvent(new CustomEvent('filemanager:selected', {
      detail: { url: trimmed, type: state.type, meta: meta || {}, trigger: state.trigger },
    }));

    modal.hide();
    if (urlInput) {
      urlInput.value = '';
    }
  };

  if (insertUrlBtn && urlInput) {
    insertUrlBtn.addEventListener('click', (event) => {
      event.preventDefault();
      const value = urlInput.value.trim();
      if (value) {
        selectFile(value, { from: 'url' });
      }
    });
  }

  if (uploadForm) {
    uploadForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (!fileInput || !fileInput.files || fileInput.files.length === 0) {
        uploadStatus.innerHTML = '<div class="alert alert-warning mb-0">Selecione um arquivo</div>';
        return;
      }

      uploadBtn.disabled = true;
      uploadStatus.innerHTML = '<div class="alert alert-info mb-0">Enviando...</div>';

      const file = fileInput.files[0];
      const cfg = getConfig();
      const formData = new FormData();
      formData.append('file', file);
      formData.append('original_filename', file.name);
      formData.append('description', (descriptionInput && descriptionInput.value) ? descriptionInput.value : file.name);
      formData.append('filetag', cfg.filetag);
      const csrf = getCSRFToken();
      if (csrf) {
        formData.append('csrf_token', csrf);
      }

      let response;
      let body = '';
      try {
        response = await fetch('/files/upload', { method: 'POST', body: formData });
        body = await response.text();
      } catch (error) {
        console.error('[filemanager-modal] upload error', error);
        uploadStatus.innerHTML = '<div class="alert alert-danger mb-0">Erro ao fazer upload</div>';
        uploadBtn.disabled = false;
        return;
      }

      if (!response.ok || body.indexOf('alert-danger') !== -1 || body.toLowerCase().indexOf('error') !== -1) {
        uploadStatus.innerHTML = '<div class="alert alert-danger mb-0">Erro ao fazer upload. Verifique o arquivo.</div>';
        uploadBtn.disabled = false;
        return;
      }

      uploadStatus.innerHTML = '<div class="alert alert-success mb-0">Upload concluído. Atualizando lista...</div>';
      fileInput.value = '';
      if (descriptionInput) {
        descriptionInput.value = '';
      }
      setTimeout(() => {
        uploadStatus.innerHTML = '';
        uploadBtn.disabled = false;
        loadList();
      }, 800);
    });
  }

  modalEl.addEventListener('hidden.bs.modal', () => {
    if (uploadStatus) uploadStatus.innerHTML = '';
    stopMediaPlayback();
  });

  const open = (options = {}) => {
    state.type = options.type || 'image';
    state.onSelect = options.onSelect || null;
    state.filetag = options.filetag || '';
    state.urlPlaceholder = options.urlPlaceholder || '';
    state.trigger = options.trigger || null;
    setTextContent();
    loadList();
    modal.show();
  };

  window.FileManagerModal = { open, hide: () => modal.hide() };
})();
